/*
 * World map geometry for the partner locator, pre-rendered offline from
 * Natural Earth land data (world-atlas, public domain) so the page needs no
 * map library or tiles.
 *
 * Projection: equirectangular on a 1000 x 394 canvas covering latitudes
 * 84N to 58S. Use `project()` for any coordinate placed on the map.
 */

export const MAP_W = 1000;
export const MAP_H = 394;

export function project(lat: number, lng: number): [number, number] {
    return [((lng + 180) / 360) * MAP_W, ((84 - lat) / 142) * MAP_H];
}

